(function () {
  $(function () {
    var $block;
    $block = $('.quantity-box');
    if (!$block.length) {
      return;
    }
    return $block.each(function () {
      var $btnDown, $btnUp, $field, $thisBlock;
      $thisBlock = $(this);
      $field = $thisBlock.find('.quantity-box__field');
      $btnDown = $thisBlock.find('.quantity-box__control_minus');
      $btnUp = $thisBlock.find('.quantity-box__control_plus');
      $field.inputmask({
        alias: 'numeric',
        allowMinus: false
      });
      $field.on('blur', function () {
        if ($field.val() < 1) {
          return $field.val(1);
        }
      });
      $btnUp.on('click', function (e) {
        var val;
        val = parseInt($field.val());
        return $field.val(val += 1);
      });
      return $btnDown.on('click', function (e) {
        var val;
        val = parseInt($field.val());
        if ($field.val() > 1) {
          return $field.val(val -= 1);
        } else {
          return $field.val(1);
        }
      });
    });
  });

}).call(this);

